{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공영주차요금을 두 번 미납한 것만으로 관리자가 주차 이용을 막을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공영주차요금을 두 번 미납한 것만으로는 관리자가 정당한 사유 없이 주차 이용을 거절할 수 없습니다. 조례 제9조는 관리자가 정당한 사유 없이 이용을 거절할 수 없으며, 제6호에서 이용 거절이 가능한 경우로 공영주차장 주차요금 또는 주차위반 과태료를 3회 이상 체납한 경우를 정하고 있습니다. 따라서 두 번 미납은 이 요건에 해당하지 않습니다.",
          "b_ids": "주차장:제9조, 주차장:제9조제6호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
